{"filePath":"c:\Users\SZeywall\Home-work\backend\Controllers\MetricsController.cs","content":"using System.Data;
using System.Text.Json;
using backend.Data;
using backend.Models;
using ExcelDataReader;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace backend.Controllers;

[ApiController]
[Route("api/metrics")]
public class MetricsController(AppDbContext db) : ControllerBase
{
    [HttpGet]
    public async Task<IActionResult> GetMetrics() => Ok(await db.Metrics.Include(metric => metric.Fields).Select(metric => new
    {
        metric.Id, metric.Code, metric.Name, metric.Description, metric.SourceName,
        fields = metric.Fields.Where(field => field.IsRelevant).OrderBy(field => field.DisplayOrder)
    }).ToListAsync());

    [HttpGet("{id}/rows")]
    public async Task<IActionResult> GetRows(int id, [FromQuery] int page = 1, [FromQuery] int pageSize = 25, [FromQuery] string? search = null)
    {
        var metric = await db.Metrics.Include(item => item.Fields).FirstOrDefaultAsync(item => item.Id == id);
        if (metric is null) return NotFound();
        pageSize = Math.Clamp(pageSize, 1, 100);
        var batches = db.ImportBatches.Where(batch => batch.MetricId == id);
        var rows = db.MetricRows.Where(row => batches.Any(batch => batch.Id == row.ImportBatchId));
        if (!string.IsNullOrWhiteSpace(search)) rows = rows.Where(row => row.ValuesJson.Contains(search));
        var total = await rows.CountAsync();
        var data = await rows.OrderByDescending(row => row.Id).Skip((page - 1) * pageSize).Take(pageSize).Select(row => new { row.Id, row.ImportBatchId, row.ValuesJson }).ToListAsync();
        return Ok(new { metric = new { metric.Id, metric.Name, metric.Code }, fields = metric.Fields.Where(field => field.IsRelevant).OrderBy(field => field.DisplayOrder), page, pageSize, total, data = data.Select(row => new { row.Id, row.ImportBatchId, values = JsonSerializer.Deserialize<Dictionary<string, object>>(row.ValuesJson) }) });
    }

    [HttpGet("{id}/imports")]
    public async Task<IActionResult> GetImports(int id) => Ok(await db.ImportBatches.Where(batch => batch.MetricId == id).OrderByDescending(batch => batch.ImportedAtUtc).ToListAsync());

    [HttpPost("{id}/import")]
    public async Task<IActionResult> Import(int id, IFormFile file, [FromForm] int year, [FromForm] string period)
    {
        var metric = await db.Metrics.Include(item => item.Fields).FirstOrDefaultAsync(item => item.Id == id);
        if (metric is null) return NotFound();
        if (file.Length == 0) return BadRequest("The file is empty.");
        System.Text.Encoding.RegisterProvider(System.Text.CodePagesEncodingProvider.Instance);
        using var stream = file.OpenReadStream();
        using var reader = ExcelReaderFactory.CreateReader(stream);
        var dataSet = reader.AsDataSet(new ExcelDataSetConfiguration { ConfigureDataTable = _ => new ExcelDataTableConfiguration { UseHeaderRow = true } });
        var table = dataSet.Tables[0];
        var keys = metric.Fields.Where(field => field.IsRelevant).Select(field => field.Key).ToHashSet(StringComparer.OrdinalIgnoreCase);
        var batch = new ImportBatch { MetricId = id, SchemaVersion = metric.Fields.Max(field => field.Version), PeriodYear = year, PeriodLabel = period, FileName = file.FileName, ImportedAtUtc = DateTime.UtcNow, RowCount = table.Rows.Count };
        foreach (DataRow row in table.Rows)
        {
            var values = table.Columns.Cast<DataColumn>().Where(column => keys.Contains(column.ColumnName)).ToDictionary(column => column.ColumnName, column => row[column] == DBNull.Value ? null : row[column].ToString());
            batch.Rows.Add(new MetricRow { ValuesJson = JsonSerializer.Serialize(values) });
        }
        db.ImportBatches.Add(batch);
        await db.SaveChangesAsync();
        return Ok(new { batch.Id, batch.FileName, batch.RowCount, batch.SchemaVersion });
    }
}
"}

